class Solution {

    /**
     * @param Integer $n
     * @param Integer[][] $edges
     * @return Integer[]
     */
    function countSubgraphsForEachDiameter(int $n, array $edges): array {
        // Build adjacency list
        $graph = array_fill(1, $n, []);
        foreach ($edges as $e) {
            $graph[$e[0]][] = $e[1];
            $graph[$e[1]][] = $e[0];
        }

        $res = array_fill(1, $n-1, 0);

        // We'll iterate over all subsets of nodes with size at least 2
        // and check:
        // 1) if they form a connected subtree
        // 2) find the max distance between any two cities in that subtree, i.e. its diameter
        //
        // Since n <= 15, 2^15 subsets is feasible.

        // Helper to check connectivity of subset and also get a node in subset for BFS start
        function isConnectedAndGetStartNode(array $subset, int $n, array &$graph): array {
            $nodes = [];
            for ($i = 0; $i < $n; $i++) {
                if (($subset & (1 << $i)) !== 0) {
                    $nodes[] = $i + 1;
                }
            }
            if (count($nodes) <= 1) return [false, 0];

            // BFS to check connectivity inside subset
            $visited = [];
            $queue = [];
            $visited[$nodes[0]] = true;
            $queue[] = $nodes[0];
            $count = 1;

            while (!empty($queue)) {
                $curr = array_shift($queue);
                foreach ($graph[$curr] as $nxt) {
                    if (in_array($nxt, $nodes, true) && !isset($visited[$nxt])) {
                        $visited[$nxt] = true;
                        $queue[] = $nxt;
                        $count++;
                    }
                }
            }

            return [$count === count($nodes), $nodes[0]];
        }

        // BFS to find distances within the subset from a start node
        // Returns the farthest node and its distance
        function bfsFarthest(int $start, array $nodes, array &$graph): array {
            $visited = [];
            $dist = [];
            $queue = [];
            $visited[$start] = true;
            $dist[$start] = 0;
            $queue[] = $start;

            $farthestNode = $start;
            $farthestDist = 0;

            while (!empty($queue)) {
                $curr = array_shift($queue);
                foreach ($graph[$curr] as $nxt) {
                    if (in_array($nxt, $nodes, true) && !isset($visited[$nxt])) {
                        $visited[$nxt] = true;
                        $dist[$nxt] = $dist[$curr] + 1;
                        $queue[] = $nxt;
                        if ($dist[$nxt] > $farthestDist) {
                            $farthestDist = $dist[$nxt];
                            $farthestNode = $nxt;
                        }
                    }
                }
            }
            return [$farthestNode, $farthestDist];
        }

        // Iterate subsets of nodes (bitmask from 1 to 2^n - 1)
        $maxMask = (1 << $n);
        for ($subset = 0; $subset < $maxMask; $subset++) {
            // Need at least 2 nodes
            if (popcount($subset) < 2) continue;

            // Check connectedness and get start node
            list($connected, $startNode) = isConnectedAndGetStartNode($subset, $n, $graph);
            if (!$connected) continue;

            // Get nodes in subset for quick lookup
            $nodes = [];
            for ($i = 0; $i < $n; $i++) {
                if (($subset & (1 << $i)) !== 0) {
                    $nodes[] = $i + 1;
                }
            }

            // Find diameter of the subtree:
            // 1) BFS from start node to find farthest node
            list($farthest1, $_) = bfsFarthest($startNode, $nodes, $graph);
            // 2) BFS from farthest1 to find farthest node and distance
            list($_, $diam) = bfsFarthest($farthest1, $nodes, $graph);

            if ($diam >= 1 && $diam <= $n - 1) {
                $res[$diam]++;
            }
        }

        // Return 1-based array
        $ret = [];
        for ($d = 1; $d <= $n - 1; $d++) {
            $ret[] = $res[$d];
        }
        return $ret;
    }
}

